INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (2, NULL, 'mushak_submission', 'Mushak 4.3 Submission', NULL, 'আপনার প্রতিষ্ঠানের বিপরীতে {{boe_date}} তারিখে আনিত {{item_name}} এর মূল্য ঘোষণা (মূসক ৪.৩) দাখিল করা হয়েছে। সাবমিশন আইডি: {{submission_id}}।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (3, NULL, 'bill_notification', 'Monthly Bill', NULL, 'প্রিয় {{customer_name}}, {{month}} মাসের ভ্যাট কনসালট্যান্সি ফি বাবদ বিল {{current_bill}} টাকা। মোট বকেয়া {{grand_total}} টাকা।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (4, NULL, 'collection_receipt', 'Payment Receipt', NULL, 'প্রিয় {{customer_name}}, আপনার নিকট হতে {{paid}} টাকা ফি বাবদ গ্রহণ করা হয়েছে। বর্তমান অবশিষ্ট বকেয়া {{due}} টাকা। ধন্যবাদ।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (5, NULL, 'due_reminder', 'Due Reminder', NULL, 'প্রিয় {{customer_name}}, অদ্য {{date}} তারিখ পর্যন্ত আপনার সর্বমোট বকেয়া {{due}} টাকা। বকেয়া পরিশোধের জন্য অনুরোধ করা হলো।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (6, 2, 'vat_submission', 'VAT Return Submission', NULL, 'আপনার প্রতিষ্ঠানের {{tax_period}} কর মেয়াদের ভ্যাট রিটার্ণ অনলাইনে দাখিল করা হয়েছে। সাবমিশন আইডি: {{submission_id}}।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (7, 2, 'mushak_submission', 'Mushak 4.3 Submission', NULL, 'আপনার প্রতিষ্ঠানের বিপরীতে {{boe_date}} তারিখে আনিত {{item_name}} এর মূল্য ঘোষণা (মূসক ৪.৩) দাখিল করা হয়েছে। সাবমিশন আইডি: {{submission_id}}।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (8, 2, 'bill_notification', 'Monthly Bill', NULL, 'প্রিয় {{customer_name}}, {{month}} মাসের ভ্যাট কনসালট্যান্সি ফি বাবদ বিল {{current_bill}} টাকা। মোট বকেয়া {{grand_total}} টাকা।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (9, 2, 'collection_receipt', 'Payment Receipt', NULL, 'প্রিয় {{customer_name}}, আপনার নিকট হতে {{paid}} টাকা ফি বাবদ গ্রহণ করা হয়েছে। বর্তমান অবশিষ্ট বকেয়া {{due}} টাকা। ধন্যবাদ।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (10, 2, 'due_reminder', 'Due Reminder', NULL, 'প্রিয় {{customer_name}}, অদ্য {{date}} তারিখ পর্যন্ত আপনার সর্বমোট বকেয়া {{due}} টাকা। বকেয়া পরিশোধের জন্য অনুরোধ করা হলো।
INSERT INTO "sms_templates" ("id", "admin_id", "key", "name", "description", "body", "variables", "is_active", "created_at", "updated_at") VALUES (1, NULL, 'vat_submission', 'VAT Return Submission', NULL, 'আপনার প্রতিষ্ঠান {{customer_name}} এর {{tax_period}} কর মেয়াদের ভ্যাট রিটার্ণ অনলাইনে দাখিল করা হয়েছে। সাবমিশন আইডি: {{submission_id}}।
